"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { TooltipProvider } from "@/components/ui/tooltip"
import { VersionedEditor } from "@/components/mockups/config-versioning/versioned-editor"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import {
  CASES,
  type CaseId,
  GLOBAL_PROMPT,
  LIVE_SCENARIO,
  TEST_SCENARIO,
} from "@/lib/mockups/config-versioning-data"

/**
 * Configuration versioning — DES-202, under INT-253, for PLT-4477. The spec
 * is the "Configuration versioning" requirements doc; it builds on DES-203's
 * live status (/live-scenarios) and leaves approval to DES-204.
 *
 * The three things the PRD versions, one per surface: a live scenario (save,
 * then publish), a not-live scenario (save is what runs), and the global
 * prompt (always live). The select reaches the states the ticket names:
 * a concurrent save, a summary still being written, history failing to load,
 * view-only, and a publish that fails.
 */

const SURFACES = [
  { id: "live", label: "Live scenario" },
  { id: "test", label: "Not-live scenario" },
  { id: "global", label: "Global prompt" },
] as const

type Surface = (typeof SURFACES)[number]["id"]

export default function ConfigVersioningPage() {
  const [surface, setSurface] = React.useState<Surface>("live")
  const [caseId, setCaseId] = React.useState<CaseId>("normal")

  /* A toast belongs to the surface and case that raised it. */
  React.useEffect(() => {
    toast.dismiss()
  }, [surface, caseId])

  const subject =
    surface === "live"
      ? LIVE_SCENARIO
      : surface === "test"
        ? TEST_SCENARIO
        : GLOBAL_PROMPT

  /* In the summary case the newest version's summary is still being
     written when the page opens. */
  const initial =
    caseId === "summary-pending"
      ? {
          ...subject,
          versions: subject.versions.map((version, index) =>
            index === 0 ? { ...version, summary: null } : version,
          ),
        }
      : subject

  return (
    <MockupShell
      actions={
        <>
          <Select
            onValueChange={(value) => setCaseId(value as CaseId)}
            value={caseId}
          >
            <SelectTrigger aria-label="State" size="sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="end" position="popper">
              {CASES.map((entry) => (
                <SelectItem key={entry.id} value={entry.id}>
                  {entry.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <ToggleGroup
            aria-label="Surface"
            onValueChange={(next) => {
              if (next) setSurface(next as Surface)
            }}
            size="sm"
            type="single"
            value={surface}
            variant="outline"
          >
            {SURFACES.map((entry) => (
              <ToggleGroupItem key={entry.id} value={entry.id}>
                {entry.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </>
      }
      title="Configuration versioning: save, publish, history, rollback"
    >
      <TooltipProvider>
        <AppShell
          active={surface === "global" ? "Global Prompts" : "Scenarios"}
          breadcrumb={
            surface === "global"
              ? "Global Prompts"
              : ["Scenarios", subject.name]
          }
        >
          {/* Keyed so each surface and case opens as the page would find it. */}
          <VersionedEditor
            caseId={caseId}
            initial={initial}
            key={`${surface}-${caseId}`}
          />
        </AppShell>
      </TooltipProvider>
    </MockupShell>
  )
}

"use client"

import * as React from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty"
import {
  Item,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Spinner } from "@/components/ui/spinner"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { SideBySideDiff } from "@/components/shared/line-diff"
import {
  CloseIcon,
  EditFromIcon,
} from "@/components/mockups/config-versioning/icons"
import type {
  CaseId,
  Subject,
  Version,
} from "@/lib/mockups/config-versioning-data"
import { cn } from "@/lib/utils"

/**
 * Version history as a record drawer — 1024px, the surfaces page's answer
 * for reading records opened from a list — because the PRD's compare is
 * side by side, and two columns of prompt do not fit in 448.
 *
 * The list is newest first: number, author, time, summary, and on anything
 * live whether each version has ever been live, with Live on the current
 * one. The pane on the right is the selected version against the one it
 * was edited from (the summary's own basis), or any other version picked.
 *
 * Publishing happens here, with the comparison on screen, so the review is
 * the history: Publish for a version newer than live, Roll back for an older
 * one (marker movement, no new version), and Edit from here to start a new
 * version from an earlier one. On a not-live scenario only the last exists.
 */
export function HistoryDrawer({
  open,
  onOpenChange,
  subject,
  initial,
  caseId,
  canEdit,
  editing,
  onPublish,
  onEditFrom,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  subject: Subject
  /** The version to open on, and what to compare it with. */
  initial: { n: number; against: number | null }
  caseId: CaseId
  canEdit: boolean
  /** The version open in the editor — Edit from here is absent for it. */
  editing: number
  /** Resolves false when publishing failed. */
  onPublish: (n: number) => Promise<boolean>
  onEditFrom: (n: number) => void
}) {
  return (
    <Drawer direction="right" onOpenChange={onOpenChange} open={open}>
      <DrawerContent className="sm:max-w-5xl!">
        <DrawerHeader className="flex flex-row items-start justify-between gap-4 border-b">
          <div className="flex flex-col gap-0.5">
            <DrawerTitle>Version history</DrawerTitle>
            <DrawerDescription>{subject.name}</DrawerDescription>
          </div>
          <DrawerClose asChild>
            <Button aria-label="Close" size="icon-sm" variant="ghost">
              <CloseIcon />
            </Button>
          </DrawerClose>
        </DrawerHeader>

        {/* Keyed on open, so every opening loads afresh — and the failure
            case fails every time until Try again. */}
        {open ? (
          <HistoryBody
            canEdit={canEdit}
            caseId={caseId}
            editing={editing}
            initial={initial}
            key={`${initial.n}-${initial.against}`}
            onEditFrom={onEditFrom}
            onPublish={onPublish}
            subject={subject}
          />
        ) : null}
      </DrawerContent>
    </Drawer>
  )
}

type Load = "loading" | "failed" | "ready"

function HistoryBody({
  subject,
  initial,
  caseId,
  canEdit,
  editing,
  onPublish,
  onEditFrom,
}: {
  subject: Subject
  initial: { n: number; against: number | null }
  caseId: CaseId
  canEdit: boolean
  editing: number
  onPublish: (n: number) => Promise<boolean>
  onEditFrom: (n: number) => void
}) {
  const [load, setLoad] = React.useState<Load>("loading")
  const [attempt, setAttempt] = React.useState(0)
  const [only, setOnly] = React.useState<"all" | "mine">("all")
  const [selected, setSelected] = React.useState(initial.n)
  const [against, setAgainst] = React.useState<number | null>(initial.against)

  React.useEffect(() => {
    const timer = setTimeout(
      () =>
        setLoad(
          caseId === "history-fails" && attempt === 0 ? "failed" : "ready",
        ),
      600,
    )
    return () => clearTimeout(timer)
  }, [attempt, caseId])

  if (load === "loading") return <ListSkeleton />

  if (load === "failed") {
    return (
      <div className="flex flex-1 items-center justify-center p-6">
        <Empty>
          <EmptyHeader>
            <EmptyTitle>Couldn’t load versions</EmptyTitle>
            <EmptyDescription>
              Nothing changed. The scenario and what callers hear are as they
              were.
            </EmptyDescription>
          </EmptyHeader>
          <EmptyContent>
            <Button
              onClick={() => {
                setLoad("loading")
                setAttempt((count) => count + 1)
              }}
              size="lg"
              variant="outline"
            >
              Try again
            </Button>
          </EmptyContent>
        </Empty>
      </div>
    )
  }

  const shown = subject.versions.filter(
    (version) => only === "all" || version.mine,
  )
  const version =
    subject.versions.find((item) => item.n === selected) ?? subject.versions[0]
  /* Against the version it was edited from — the summary's own basis — or,
     when that one is older than the list goes, the next one down. */
  const find = (n: number | null) =>
    subject.versions.find((item) => item.n === n) ?? null
  const compare =
    find(against) ??
    find(version.editedFrom) ??
    subject.versions.find((item) => item.n < version.n) ??
    null

  return (
    <div className="flex min-h-0 flex-1">
      <aside className="flex w-80 shrink-0 flex-col border-e">
        <div className="border-b p-3">
          <ToggleGroup
            aria-label="Whose versions"
            onValueChange={(value) => {
              if (value) setOnly(value as "all" | "mine")
            }}
            size="sm"
            type="single"
            value={only}
            variant="outline"
          >
            <ToggleGroupItem value="all">All</ToggleGroupItem>
            <ToggleGroupItem value="mine">Only mine</ToggleGroupItem>
          </ToggleGroup>
        </div>

        <div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-3">
          {shown.length === 0 ? (
            <Empty>
              <EmptyHeader>
                <EmptyTitle>No versions of yours yet</EmptyTitle>
              </EmptyHeader>
              <EmptyContent>
                <Button onClick={() => setOnly("all")} variant="outline">
                  Show all
                </Button>
              </EmptyContent>
            </Empty>
          ) : (
            shown.map((item) => (
              <VersionRow
                key={item.n}
                live={subject.marker !== null}
                marker={subject.marker}
                onSelect={() => {
                  setSelected(item.n)
                  setAgainst(null)
                }}
                selected={item.n === version.n}
                version={item}
              />
            ))
          )}
        </div>
      </aside>

      <VersionPane
        against={compare}
        canEdit={canEdit}
        editing={editing}
        key={version.n}
        onAgainst={setAgainst}
        onEditFrom={onEditFrom}
        onPublish={onPublish}
        caseId={caseId}
        subject={subject}
        version={version}
      />
    </div>
  )
}

function VersionRow({
  version,
  marker,
  live,
  selected,
  onSelect,
}: {
  version: Version
  marker: number | null
  live: boolean
  selected: boolean
  onSelect: () => void
}) {
  return (
    <Item
      asChild
      className={cn(
        "cursor-pointer text-start hover:bg-muted/50",
        selected && "border-primary ring-1 ring-primary",
      )}
      size="sm"
      variant="outline"
    >
      <button onClick={onSelect} type="button">
        <ItemContent className="min-w-0">
          <ItemTitle className="tabular-nums">
            v{version.n}
            {version.n === marker ? (
              <Badge
                className="bg-success-tint text-success-tint-foreground"
                variant="secondary"
              >
                Live
              </Badge>
            ) : live && version.everLive ? (
              <Badge
                className="bg-muted text-muted-foreground"
                variant="secondary"
              >
                Was live
              </Badge>
            ) : null}
          </ItemTitle>
          <ItemDescription className="tabular-nums">
            {version.author} · {version.at}
          </ItemDescription>
          <Summary className="line-clamp-2" version={version} />
        </ItemContent>
      </button>
    </Item>
  )
}

/** A version's summary, or where it is: still being written, or not made. */
function Summary({
  version,
  className,
}: {
  version: Version
  className?: string
}) {
  if (version.summary === null) {
    return (
      <span className="flex items-center gap-2 text-sm text-muted-foreground">
        <Spinner className="size-3.5" />
        Writing summary
      </span>
    )
  }
  if (version.summary === "failed") {
    return (
      <span className="text-sm text-muted-foreground">
        No summary — compare to see the change
      </span>
    )
  }
  return <p className={cn("text-sm", className)}>{version.summary}</p>
}

function VersionPane({
  subject,
  version,
  against,
  onAgainst,
  caseId,
  canEdit,
  editing,
  onPublish,
  onEditFrom,
}: {
  subject: Subject
  version: Version
  against: Version | null
  onAgainst: (n: number) => void
  caseId: CaseId
  canEdit: boolean
  editing: number
  onPublish: (n: number) => Promise<boolean>
  onEditFrom: (n: number) => void
}) {
  const [publishing, setPublishing] = React.useState(false)
  const [failed, setFailed] = React.useState(false)
  const marker = subject.marker
  const isLive = version.n === marker

  /* Publish moves the marker forward, Roll back moves it back. Neither
     makes a version (PRD). Absent on a not-live scenario, and on the live
     version itself. */
  const markerAction =
    marker === null || isLive
      ? null
      : version.n > marker
        ? `Publish v${version.n}`
        : `Roll back to v${version.n}`

  const publish = async () => {
    setPublishing(true)
    setFailed(false)
    const ok = await onPublish(version.n)
    setPublishing(false)
    if (!ok) setFailed(true)
  }

  const changed = subject.fields.filter(
    (field) => against && against.body[field.id] !== version.body[field.id],
  )
  const unchanged = subject.fields.filter(
    (field) => against && against.body[field.id] === version.body[field.id],
  )

  return (
    <section className="flex min-w-0 flex-1 flex-col gap-6 overflow-y-auto p-6">
      <div className="flex items-start justify-between gap-4">
        <div className="flex min-w-0 flex-col gap-1">
          <h2 className="flex items-center gap-2 text-base font-medium tabular-nums">
            v{version.n}
            {isLive ? (
              <Badge
                className="bg-success-tint text-success-tint-foreground"
                variant="secondary"
              >
                Live
              </Badge>
            ) : null}
          </h2>
          <p className="text-sm text-muted-foreground tabular-nums">
            {version.author} · {version.at}
            {version.editedFrom ? ` · edited from v${version.editedFrom}` : ""}
          </p>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {version.n === editing ? null : (
            <Permission allowed={canEdit}>
              <Button
                disabled={!canEdit || publishing}
                onClick={() => onEditFrom(version.n)}
                variant="outline"
              >
                <EditFromIcon />
                Edit from here
              </Button>
            </Permission>
          )}
          {markerAction ? (
            <Permission allowed={canEdit}>
              <Button disabled={!canEdit || publishing} onClick={publish}>
                {publishing ? <Spinner /> : null}
                {failed ? "Try again" : markerAction}
              </Button>
            </Permission>
          ) : null}
        </div>
      </div>

      {failed ? (
        <Alert className="bg-destructive-tint" variant="destructive">
          <AlertTitle>Couldn’t publish v{version.n}</AlertTitle>
          <AlertDescription>
            Callers still hear v{marker}. Nothing else changed.
          </AlertDescription>
        </Alert>
      ) : null}

      {markerAction && caseId !== "publish-fails" ? (
        <p className="text-sm text-muted-foreground">
          {version.n > (marker ?? 0)
            ? `Callers hear v${version.n} from the next call.`
            : `Callers go back to v${version.n} from the next call. No version is made, and v${marker} stays in history.`}
        </p>
      ) : null}

      <Summary version={version} />

      {against ? (
        <div className="flex flex-col gap-4">
          <div className="flex items-center gap-3">
            <span className="text-sm text-muted-foreground">Compared with</span>
            <Select
              onValueChange={(value) => onAgainst(Number(value))}
              value={String(against.n)}
            >
              <SelectTrigger aria-label="Compared with" size="sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent position="popper">
                {subject.versions
                  .filter((item) => item.n !== version.n)
                  .map((item) => (
                    <SelectItem key={item.n} value={String(item.n)}>
                      v{item.n}
                      {item.n === marker ? " (live)" : ""}
                      {item.n === version.editedFrom ? " (edited from)" : ""}
                    </SelectItem>
                  ))}
              </SelectContent>
            </Select>
          </div>

          {changed.map((field) => (
            <div className="flex flex-col gap-2" key={field.id}>
              <span className="text-sm font-medium">{field.label}</span>
              <div className="grid grid-cols-2 text-xs text-muted-foreground tabular-nums">
                <span className="px-3">v{against.n}</span>
                <span className="px-3">v{version.n}</span>
              </div>
              <SideBySideDiff
                after={version.body[field.id]}
                before={against.body[field.id]}
              />
            </div>
          ))}

          {changed.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              Same as v{against.n}.
            </p>
          ) : unchanged.length > 0 ? (
            <p className="text-sm text-muted-foreground">
              No change: {unchanged.map((field) => field.label).join(", ")}
            </p>
          ) : null}
        </div>
      ) : (
        <p className="text-sm text-muted-foreground">The first version.</p>
      )}
    </section>
  )
}

/** A greyed action says why on hover, as DES-203's Live switch does. */
function Permission({
  allowed,
  children,
}: {
  allowed: boolean
  children: React.ReactNode
}) {
  if (allowed) return <>{children}</>
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span className="flex">{children}</span>
      </TooltipTrigger>
      <TooltipContent>You can view versions but not change them</TooltipContent>
    </Tooltip>
  )
}

function ListSkeleton() {
  return (
    <div className="flex min-h-0 flex-1">
      <aside className="flex w-80 shrink-0 flex-col gap-2 border-e p-3">
        {Array.from({ length: 5 }, (_, index) => (
          <Skeleton
            className="h-20 w-full motion-reduce:animate-none"
            key={index}
          />
        ))}
      </aside>
      <div className="flex flex-1 flex-col gap-4 p-6">
        <Skeleton className="h-5 w-40 motion-reduce:animate-none" />
        <Skeleton className="h-4 w-2/3 motion-reduce:animate-none" />
        <Skeleton className="h-40 w-full motion-reduce:animate-none" />
      </div>
    </div>
  )
}

"use client"

import {
  ArrowDown01Icon,
  ArrowLeft02Icon,
  Cancel01Icon,
  MoreHorizontalIcon,
  PencilEdit02Icon,
  PlayIcon,
  WorkHistoryIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The editor's header, as DES-203 left it: try it, and its overflow menu. */
export const RunScenarioIcon = icon(PlayIcon, "RunScenarioIcon")
export const MoreActionsIcon = icon(MoreHorizontalIcon, "MoreActionsIcon")
/** Opens the Live popover. */
export const StatusMenuIcon = icon(ArrowDown01Icon, "StatusMenuIcon")

/** Opens version history. */
export const HistoryIcon = icon(WorkHistoryIcon, "HistoryIcon")
/** Loads an earlier version into the editor as the starting point. */
export const EditFromIcon = icon(PencilEdit02Icon, "EditFromIcon")
/** Leaves "editing from an earlier version" and goes back to the newest. */
export const BackToNewestIcon = icon(ArrowLeft02Icon, "BackToNewestIcon")
/** Closes a drawer. */
export const CloseIcon = icon(Cancel01Icon, "CloseIcon")

"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Textarea } from "@/components/ui/textarea"
import { EditorHeader } from "@/components/mockups/config-versioning/editor-header"
import { HistoryDrawer } from "@/components/mockups/config-versioning/history-drawer"
import { BackToNewestIcon } from "@/components/mockups/config-versioning/icons"
import { SaveReview } from "@/components/mockups/config-versioning/save-review"
import {
  type CaseId,
  RIVAL,
  type Subject,
  type Version,
} from "@/lib/mockups/config-versioning-data"

/**
 * The editor for anything versioned — a scenario's Scenario tab, or the
 * global prompt — cut to what DES-202 changes.
 *
 *  - Save makes a version. Live or not, the save review says what the save
 *    does to callers (save-review.tsx).
 *  - On a live item with saves ahead of the marker, one row under the header
 *    says which versions are not live and offers Review and publish. It is
 *    the ticket's draft indicator, unpublished state and publish action in
 *    one place, and it is absent when there is nothing to publish.
 *  - History (history-drawer.tsx) is where publishing, rolling back and
 *    "edit from here" happen, with the comparison on screen.
 *  - Edit from here opens an earlier version as the starting point, says so
 *    above the fields, and saves as a new version on top (PRD).
 */
export function VersionedEditor({
  initial,
  caseId,
}: {
  initial: Subject
  caseId: CaseId
}) {
  const [subject, setSubject] = React.useState(initial)
  const [base, setBase] = React.useState(initial.versions[0].n)
  const [draft, setDraft] = React.useState(initial.versions[0].body)
  const [reviewing, setReviewing] = React.useState(false)
  const [history, setHistory] = React.useState<{
    n: number
    against: number | null
  } | null>(null)
  const [rival, setRival] = React.useState<Version | null>(null)

  const canEdit = caseId !== "view-only"
  const newest = subject.versions[0]
  const baseVersion =
    subject.versions.find((version) => version.n === base) ?? newest
  const editingFrom = base !== newest.n && !rival
  const changes = subject.fields.filter(
    (field) => draft[field.id] !== newest.body[field.id],
  ).length
  const live = subject.marker !== null
  const ahead = live
    ? subject.versions.filter((v) => v.n > subject.marker!)
    : []

  /* A summary for a fresh save arrives a moment later (PRD: generation never
     blocks the save). In the pending case it never does. */
  React.useEffect(() => {
    if (caseId === "summary-pending") return
    if (newest.summary !== null) return
    const timer = setTimeout(
      () =>
        setSubject((current) => ({
          ...current,
          versions: current.versions.map((version) =>
            version.summary === null
              ? { ...version, summary: summarise(current, version) }
              : version,
          ),
        })),
      2500,
    )
    return () => clearTimeout(timer)
  }, [caseId, newest.summary])

  function openReview() {
    /* The conflict case: someone else's save lands after this page opened. */
    if (caseId === "conflict" && !rival) {
      const theirs: Version = {
        ...RIVAL,
        n: newest.n + 1,
        editedFrom: newest.n,
        body: {
          ...newest.body,
          [subject.fields[0].id]:
            `${newest.body[subject.fields[0].id]} I'm calling from the Olaya branch.`,
        },
      }
      setRival(theirs)
      setSubject((current) => ({
        ...current,
        versions: [theirs, ...current.versions],
      }))
    }
    setReviewing(true)
  }

  function save() {
    const n = subject.versions[0].n + 1
    const made: Version = {
      n,
      author: "You",
      mine: true,
      at: "Just now",
      editedFrom: base,
      summary: null,
      everLive: false,
      body: draft,
    }
    setSubject((current) => ({
      ...current,
      versions: [made, ...current.versions],
    }))
    setBase(n)
    setRival(null)
    setReviewing(false)
    toast.success(`Saved as v${n}`, {
      description: live
        ? `Callers still hear v${subject.marker}.`
        : "It runs from the next call.",
    })
  }

  function discard() {
    const before = { draft, base }
    setDraft(newest.body)
    setBase(newest.n)
    toast("Changes discarded", {
      action: {
        label: "Undo",
        onClick: () => {
          setDraft(before.draft)
          setBase(before.base)
        },
      },
    })
  }

  async function publish(n: number): Promise<boolean> {
    await new Promise((resolve) => setTimeout(resolve, 900))
    if (caseId === "publish-fails") return false
    const before = { marker: subject.marker, published: subject.published }
    setSubject((current) => ({
      ...current,
      marker: n,
      published: { by: "You", at: "Just now" },
      versions: current.versions.map((version) =>
        version.n === n ? { ...version, everLive: true } : version,
      ),
    }))
    setHistory(null)
    toast.success(`v${n} is live`, {
      description:
        before.marker !== null && n < before.marker
          ? `Rolled back from v${before.marker}. No version was made.`
          : "Callers hear it from the next call.",
      action: {
        label: "Undo",
        onClick: () =>
          setSubject((current) => ({
            ...current,
            marker: before.marker,
            published: before.published,
          })),
      },
    })
    return true
  }

  function editFrom(n: number) {
    const version = subject.versions.find((item) => item.n === n)
    if (!version) return
    setBase(n)
    setDraft(version.body)
    setHistory(null)
  }

  function toggleLive(on: boolean) {
    const before = { marker: subject.marker, published: subject.published }
    setSubject((current) => ({
      ...current,
      marker: on ? current.versions[0].n : null,
      published: on ? { by: "You", at: "Just now" } : null,
      versions: on
        ? current.versions.map((version, index) =>
            index === 0 ? { ...version, everLive: true } : version,
          )
        : current.versions,
    }))
    toast(
      on ? `${subject.name} is live` : `${subject.name} is no longer live`,
      {
        description: on
          ? `v${newest.n} is the live version. Saves wait for a publish.`
          : `v${newest.n} runs from the next call. Saves apply straight away.`,
        action: {
          label: "Undo",
          onClick: () =>
            setSubject((current) => ({
              ...current,
              marker: before.marker,
              published: before.published,
            })),
        },
      },
    )
  }

  return (
    <main className="mx-auto flex w-full max-w-3xl flex-col gap-6 p-8 pb-28">
      <EditorHeader
        base={base}
        canEdit={canEdit}
        onOpenHistory={() => setHistory({ n: newest.n, against: null })}
        onToggleLive={toggleLive}
        subject={subject}
      />

      {ahead.length > 0 ? (
        <Item variant="outline">
          <ItemContent>
            <ItemTitle className="tabular-nums">
              {ahead.length === 1
                ? `v${ahead[0].n} isn’t live yet`
                : `v${ahead[ahead.length - 1].n} to v${ahead[0].n} aren’t live yet`}
            </ItemTitle>
            <ItemDescription className="tabular-nums">
              Callers hear v{subject.marker}.
            </ItemDescription>
          </ItemContent>
          <ItemActions>
            <Button
              onClick={() =>
                setHistory({ n: newest.n, against: subject.marker })
              }
            >
              Review and publish
            </Button>
          </ItemActions>
        </Item>
      ) : null}

      {editingFrom ? (
        <Alert>
          <AlertTitle className="tabular-nums">Editing from v{base}</AlertTitle>
          <AlertDescription className="tabular-nums">
            {baseVersion.author}, {baseVersion.at}. Saving makes v{newest.n + 1}{" "}
            with this content; v{newest.n} stays in history.
          </AlertDescription>
          <AlertAction>
            <Button onClick={discard} size="sm" variant="outline">
              <BackToNewestIcon />
              Back to v{newest.n}
            </Button>
          </AlertAction>
        </Alert>
      ) : null}

      <FieldGroup>
        {subject.fields.map((field) => (
          <Field key={field.id}>
            <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
            {field.multiline ? (
              <Textarea
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                rows={6}
                value={draft[field.id]}
              />
            ) : (
              <Input
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                value={draft[field.id]}
              />
            )}
          </Field>
        ))}
      </FieldGroup>

      {changes > 0 ? (
        <Card className="sticky bottom-4" size="sm">
          <CardContent className="flex items-center gap-3">
            <span className="text-sm tabular-nums">
              {changes === 1 ? "1 change" : `${changes} changes`}
            </span>
            <div className="ms-auto flex items-center gap-2">
              <Button onClick={discard} variant="ghost">
                Discard
              </Button>
              <Button onClick={openReview}>Review and save</Button>
            </div>
          </CardContent>
        </Card>
      ) : null}

      <SaveReview
        base={base}
        draft={draft}
        onOpenChange={setReviewing}
        onSave={save}
        open={reviewing}
        rival={rival}
        subject={subject}
      />

      <HistoryDrawer
        canEdit={canEdit}
        caseId={caseId}
        editing={base}
        initial={history ?? { n: newest.n, against: null }}
        onEditFrom={editFrom}
        onOpenChange={(open) => {
          if (!open) setHistory(null)
        }}
        onPublish={publish}
        open={history !== null}
        subject={
          caseId === "view-only"
            ? {
                ...subject,
                versions: subject.versions.map((v) => ({ ...v, mine: false })),
              }
            : subject
        }
      />
    </main>
  )
}

/** A stand-in for the generated summary: which parts the save touched. */
function summarise(subject: Subject, version: Version) {
  const parent = subject.versions.find((item) => item.n === version.editedFrom)
  const touched = subject.fields
    .filter(
      (field) => parent && parent.body[field.id] !== version.body[field.id],
    )
    .map((field) => field.label)
  return touched.length
    ? `${touched.join(" and ")}: edited${version.editedFrom ? ` from v${version.editedFrom}` : ""}.`
    : `Same content as v${version.editedFrom}.`
}

